$checks = [
    'approved source hash and development approval recorded' => str_contains($addendum, '96744a64edecbde0a63fa5c55756b44e56d03dabbd00e61f8c89acc443a1846b') && str_contains($addendum, 'Implementation authorized:** YES — LOCAL DEVELOPMENT ONLY'),
    'additive immutable lineage table' => str_contains($migration, 'CREATE TABLE IF NOT EXISTS `op_rh_v2_shift_template_station_lineage`') && !preg_match('/\b(DROP|ALTER|DELETE|UPDATE)\b/i', preg_replace('/--.*$/m', '', $migration)),
    'unique station/source identity' => str_contains($migration, 'UNIQUE KEY `uq_v2_shift_lineage_station_source` (`id_estacion`, `source_global_clave`)'),
    'unique station/local identity' => str_contains($migration, 'UNIQUE KEY `uq_v2_shift_lineage_station_local` (`id_estacion`, `local_clave`)'),
    'copy writer is transactionally scoped' => str_contains($service, 'function createStationCustomization') && str_contains($service, '$this->db->begin_transaction()') && str_contains($service, "'scope' => 'STATION'") && str_contains($service, '$stationId'),
    'only current active global source accepted' => str_contains($service, "scope = 'GLOBAL' AND id_estacion IS NULL AND es_activo = 1 AND version = (SELECT MAX(source_latest.version)"),
    'local identity generated by API' => str_contains($service, '\'ST\' . $stationId . \'_C\' . bin2hex(random_bytes(16))'),
    'duplicate returns existing current local without mutation' => str_contains($service, 'return [\'created\' => false, \'template\' => $current]'),
    'lineage is preserved on version detail' => str_contains($service, 'derived_from_global') && str_contains($service, 'source_global_version'),
    'existing endpoint requires station template authorization before write' => str_contains($controller, '$authInfo = $this->authorizeTemplateMutation($payload);') && str_contains($controller, '$this->templateService->createStationCustomization('),
    'direction does not receive customization capability' => str_contains($controller, 'Encargado no tiene permiso para administrar plantillas globales.'),
];
$pass = 0;
foreach ($checks as $label => $ok) { echo ($ok ? 'PASS' : 'FAIL') . ' ' . $label . PHP_EOL; $pass += $ok ? 1 : 0; }
